// API de categorias
export async function getCategories(token) {
  const response = await fetch('/api/categorias', {
    headers: { 'Authorization': `Bearer ${token}` }
  });
  if (!response.ok) throw new Error('Erro ao buscar categorias.');
  return response.json();
}
